// A real serial message controls the drawing; this is not a separate animation.
let led = 0,
  received = false;
function setup() {
  createCanvas(440, 340);
}
function draw() {
  arduinoComms.poll();
  const dark = window.theme === "dark";
  background(dark ? "#242426" : "#fafafa");
  noStroke();
  textFont("sans-serif");
  textAlign(CENTER);
  fill(dark ? "#d8d8da" : "#343436");
  textSize(22);
  text("HelloLED", width / 2, 42);
  fill(led ? "#ef6c68" : dark ? "#444448" : "#dedee0");
  circle(width / 2, 155, 116);
  fill(dark ? "#d8d8da" : "#343436");
  textSize(18);
  text(
    received ? (led ? "HIGH · on" : "LOW · off") : "Waiting for Arduino…",
    width / 2,
    254,
  );
  textSize(12);
  text("LED in D13 / GND", width / 2, 295);
}

function acceptLine(line) {
  led = Number(line.trim());
  received = true;
}

// p5comp communications: begin
////////////////////////////////////////////////////////////////////////
// Arduino ↔ p5: webserial. This code is part of your sketch.
// p5.webserial is loaded by index.html. In setup/draw you can also call connect/poll explicitly.
var arduinoComms = {
  lastLine: "",
  connected: false,
  onLine(line) {
    this.lastLine = line;
    if (typeof acceptLine === "function") acceptLine(line);
  },
  async connect(onLine) {
    if (this.connected) return;
    if (onLine) this.onLine = onLine;
    this.port = createSerial();
    await this.port.open(9600);
    this.connected = true;
  },
  poll() {
    if (!this.port?.opened()) return;
    for (let i = 0; i < 50; i++) {
      const line = this.port.readUntil("\n");
      if (!line) break;
      this.onLine(line);
    }
  },
  sendLine(line) {
    if (this.port?.opened()) return this.port.println(line);
  },
  async disconnect() {
    await this.port?.close();
    this.connected = false;
  },
};
p5.prototype.registerMethod("pre", () => arduinoComms.poll());
p5.prototype.registerMethod("afterSetup", () => {
  if (window.serialConnected) arduinoComms.connect().catch(console.error);
});
////////////////////////////////////////////////////////////////////////
// p5comp communications: end

